<script setup lang="ts">
definePageMeta({ layout: false })
const language = ref<'ja' | 'ko'>('ja')
const answer = ref('')
const landing = ref<HTMLElement | null>(null)
const mounted = ref(false)
const heroArt = ref<HTMLElement | null>(null)
const greetings = ['Yang penting, mulai dulu!', 'Hai! Klik hurufnya, yuk ✦', 'Satu huruf lagi? Kamu bisa!', 'Aku siap nemenin kamu!']
const greeting = ref(0)
const flippedCard = ref('')
const celebration = ref(0)
const feature = ref<'race' | 'path' | 'progress'>('race')
const raceInput = ref('')
const raceStroke = ref(0)
const raceKey = ref('')
const raceMistake = ref(false)
watch(raceInput, (value, previous) => {
  raceStroke.value++
  raceKey.value = value.length < previous.length ? 'Backspace' : value.at(-1) || ''
  raceMistake.value = !raceWord.startsWith(value.toLowerCase())
})
const raceWord = 'sakura'
const raceComplete = computed(() => raceInput.value.toLowerCase() === raceWord)
const features = [
  { id: 'race' as const, icon: 'bolt', title: 'Typing Race', copy: 'Latih ketepatan dan kecepatan membaca lewat tantangan mengetik.', to: '/typing-race', label: 'Main Typing Race' },
  { id: 'path' as const, icon: 'target', title: 'Perjalanan Belajar', copy: 'Mulai dengan tes penempatan, ikuti bab, lalu uji pemahaman lewat kuis.', to: '/perjalanan', label: 'Lihat perjalanan belajar' },
  { id: 'progress' as const, icon: 'chart', title: 'Progres & Achievement', copy: 'Lihat aktivitas, akurasi, raport, dan pencapaian dari latihanmu.', to: '/progres', label: 'Buka progres belajar' },
]
const selectedFeature = computed(() => features.find(item => item.id === feature.value)!)
const scrollProgress = ref(0)
let revealObserver: IntersectionObserver | undefined
function greet() {
  greeting.value = (greeting.value + 1) % greetings.length
}
function tilt(event: PointerEvent) {
  if (event.pointerType !== 'mouse' || !heroArt.value) return
  const bounds = heroArt.value.getBoundingClientRect()
  heroArt.value.style.setProperty('--pointer-x', `${(event.clientX - bounds.left - bounds.width / 2) / 25}px`)
  heroArt.value.style.setProperty('--pointer-y', `${(event.clientY - bounds.top - bounds.height / 2) / 25}px`)
}
function resetTilt() {
  heroArt.value?.style.setProperty('--pointer-x', '0px')
  heroArt.value?.style.setProperty('--pointer-y', '0px')
}
function updateScroll() {
  const total = document.documentElement.scrollHeight - window.innerHeight
  scrollProgress.value = total > 0 ? Math.min(1, Math.max(0, window.scrollY / total)) : 0
}
function choose(choice: string) {
  answer.value = choice
  if (choice === demo.value.reading) celebration.value++
}
function backToTop() {
  window.scrollTo({ top: 0, behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth' })
}
const store = useLearningStore()
const intro = useIntro()
const demo = computed(() => language.value === 'ja'
  ? { glyph: 'あ', script: 'HIRAGANA', reading: 'a', choices: ['a', 'i', 'u', 'e'] }
  : { glyph: '나', script: 'HANGUL', reading: 'na', choices: ['ga', 'na', 'da', 'ma'] })
watch(language, () => { answer.value = '' })
onMounted(() => {
  mounted.value = true
  void store.init()
  revealObserver = new IntersectionObserver(entries => {
    for (const entry of entries) {
      if (!entry.isIntersecting) continue
      entry.target.classList.add('lp-revealed')
      revealObserver?.unobserve(entry.target)
    }
  }, { threshold: 0.12 })
  landing.value?.querySelectorAll('.lp-section-heading, .lp-language, .lp-steps article, .lp-try-copy, .lp-demo-card, .lp-questions details, .lp-final').forEach(element => revealObserver?.observe(element))
  window.addEventListener('scroll', updateScroll, { passive: true })
  updateScroll()
})
onBeforeUnmount(() => {
  revealObserver?.disconnect()
  window.removeEventListener('scroll', updateScroll)
})
async function start(selected?: 'ja' | 'ko') {
  await store.init()
  store.updateSettings({ language: selected || language.value })
  intro.finish()
  await navigateTo('/belajar')
}
const faqs = [
  { question: 'Aku belum bisa sama sekali. Bisa mulai di sini?', answer: 'Bisa! Mulai dari huruf dasar dalam kelompok kecil, lihat bacaannya, lalu coba latihan. Tidak perlu punya dasar bahasa Jepang atau Korea.' },
  { question: 'Harus buat akun dulu?', answer: 'Tidak. Kamu bisa langsung membuka materi dan berlatih tanpa mendaftar.' },
  { question: 'Progres belajarku disimpan di mana?', answer: 'Progres tersimpan di browser yang kamu pakai. Unduh cadangan lewat Pengaturan sebelum pindah perangkat atau membersihkan data browser, lalu impor cadanganmu untuk melanjutkan.' },
  { question: 'Bisa belajar Jepang dan Korea sekaligus?', answer: 'Bisa. Ganti bahasa dari halaman belajar kapan saja. Materi Jepang mencakup Hiragana dan Katakana, sedangkan materi Korea mencakup Hangul.' },
]
</script>

<template>
  <div ref="landing" class="landing" :data-ready="mounted">
    <div class="lp-scroll-meter" :style="{ transform: `scaleX(${scrollProgress})` }" aria-hidden="true" />
    <a class="skip-link" href="#main">Lewati ke konten</a>
    <header class="lp-header lp-wrap">
      <NuxtLink to="/" class="lp-brand" aria-label="KanaLearn beranda"><span class="lp-mark" lang="ja">か</span>Kana<span>Learn</span><small>BETA</small></NuxtLink>
      <nav aria-label="Navigasi landing page"><a href="#fitur">Fitur</a><a href="#cara-belajar">Cara belajar</a><a href="#bahasa">Pilihan bahasa</a><a href="#faq">FAQ</a></nav>
      <NuxtLink to="/belajar" class="lp-nav-cta">Buka aplikasi <AppIcon name="arrow" :size="16" /></NuxtLink>
    </header>
    <main id="main" tabindex="-1">
      <section class="lp-hero lp-wrap" aria-labelledby="lp-title">
        <div class="lp-hero-copy"><span class="lp-eyebrow"><i /> HURUF BARU, PETUALANGAN BARU</span><h1 id="lp-title">Dari asing,<br>jadi <span>aku bisa<sup aria-hidden="true">✦</sup></span>.</h1><p>Belajar huruf Jepang & Korea, satu langkah kecil setiap hari. Kenali hurufnya, coba latihannya, temukan ritmemu.</p><div class="lp-hero-actions"><button class="lp-button" @click="start()">Mulai belajar gratis <AppIcon name="arrow" :size="20" /></button><a href="#coba" class="lp-demo-link"><AppIcon name="play" :size="16" /> Coba dulu, yuk</a></div><div class="lp-perks"><span><AppIcon name="check" :size="15" /> Tanpa akun</span><span><AppIcon name="check" :size="15" /> Mulai dari nol</span><span><AppIcon name="check" :size="15" /> Sesuai ritmemu</span></div></div>
        <div ref="heroArt" class="lp-hero-art" @pointermove="tilt" @pointerleave="resetTilt"><div class="lp-orbit" aria-hidden="true" /><Transition name="lp-greeting" mode="out-in"><span :key="greeting" class="lp-speech" aria-live="polite">{{ greetings[greeting] }}</span></Transition><span class="lp-art-star" aria-hidden="true">✦</span><button class="lp-glyph lp-glyph-ja" :class="{ flipped: flippedCard === 'ja' }" :aria-pressed="flippedCard === 'ja'" aria-label="Balik kartu Hiragana" @click="flippedCard = flippedCard === 'ja' ? '' : 'ja'"><span :lang="flippedCard === 'ja' ? 'en' : 'ja'">{{ flippedCard === 'ja' ? 'a' : 'あ' }}</span><small>{{ flippedCard === 'ja' ? 'DIBACA: A' : 'KLIK UNTUK BALIK' }}</small></button><button class="lp-glyph lp-glyph-ko" :class="{ flipped: flippedCard === 'ko' }" :aria-pressed="flippedCard === 'ko'" aria-label="Balik kartu Hangul" @click="flippedCard = flippedCard === 'ko' ? '' : 'ko'"><span :lang="flippedCard === 'ko' ? 'en' : 'ko'">{{ flippedCard === 'ko' ? 'han' : '한' }}</span><small>{{ flippedCard === 'ko' ? 'DIBACA: HAN' : 'KLIK UNTUK BALIK' }}</small></button><div class="lp-mascot-button"><KikoMascot class="lp-kiko" @interact="greet" /></div><span class="lp-kiko-label">● &nbsp; KIKO · TEMAN BELAJARMU</span><span class="lp-art-spark" aria-hidden="true">✳</span></div>
      </section>
      <div class="lp-ticker"><div class="lp-wrap"><span>HIRAGANA <b lang="ja">あ</b></span><i>✦</i><span>KATAKANA <b lang="ja">ア</b></span><i>✦</i><span>HANGUL <b lang="ko">한</b></span><i>✦</i><span>LATIHAN INTERAKTIF <AppIcon name="bolt" :size="22" /></span><i>✦</i><span>PROGRES BELAJAR <AppIcon name="chart" :size="22" /></span></div></div>
      <section id="bahasa" class="lp-section lp-wrap" aria-labelledby="language-title"><div class="lp-section-heading"><div><span class="lp-eyebrow">01 / PILIH PETUALANGANMU</span><h2 id="language-title">Mau mulai dari bahasa apa?</h2></div><p>Dua bahasa. Banyak penemuan baru.<br>Pilih satu dulu, ganti kapan saja.</p></div><div class="lp-languages"><button class="lp-language lp-japanese" @click="start('ja')"><div class="lp-language-top"><span>こんにちは!</span><AppIcon name="arrow" :size="22" /></div><div class="lp-language-body"><div><h3>Bahasa Jepang</h3><p>Kenali Hiragana & Katakana,<br>lalu baca kata pertamamu.</p><small>MULAI DARI HURUF DASAR</small></div><span class="lp-language-glyph" lang="ja" aria-hidden="true">あ<span>ア</span></span></div></button><button class="lp-language lp-korean" @click="start('ko')"><div class="lp-language-top"><span>안녕하세요!</span><AppIcon name="arrow" :size="22" /></div><div class="lp-language-body"><div><h3>Bahasa Korea</h3><p>Kenali Hangul, dari huruf dasar<br>sampai membaca kata.</p><small>SATU HURUF SETIAP LANGKAH</small></div><span class="lp-language-glyph" lang="ko" aria-hidden="true">한<span>글</span></span></div></button></div></section>
      <section id="cara-belajar" class="lp-method"><div class="lp-wrap lp-section"><div class="lp-centered"><span class="lp-eyebrow">02 / SEDIKIT DEMI SEDIKIT, JADI BISA</span><h2>Belajar yang terasa seperti bermain.</h2><p>Tak perlu langsung hafal semuanya. Cukup mulai dari langkah pertama.</p></div><div class="lp-steps"><article><div class="lp-step-art lp-letter-art"><span lang="ja">あ<small>a</small></span><span lang="ja">い<small>i</small></span><span lang="ja">う<small>u</small></span></div><span class="lp-step-number">01</span><h3>Kenalan dengan huruf</h3><p>Buka kartu, lihat bacaannya. Pelajari huruf dalam kelompok kecil supaya lebih mudah diingat.</p></article><article><div class="lp-step-art lp-choice-art"><span lang="ja">あ dibaca apa?</span><div><span>✓ a</span><span>i</span><span>u</span></div></div><span class="lp-step-number">02</span><h3>Coba, salah, coba lagi</h3><p>Pilih jawaban atau ketik sendiri. Santai tanpa timer, atau uji kecepatanmu di mode Sprint.</p></article><article><div class="lp-step-art lp-progress-art"><AppIcon name="chart" :size="34" /><div><span /><span /><span /><span /><span /></div><small>SETIAP LATIHAN BERARTI</small></div><span class="lp-step-number">03</span><h3>Lihat kamu berkembang</h3><p>Pantau akurasi dan riwayat latihan. Ulang huruf yang belum melekat, lalu lanjutkan perjalananmu.</p></article></div></div></section>
