      <section id="fitur" class="lp-section lp-wrap lp-features" aria-labelledby="features-title">
        <div class="lp-section-heading"><div><span class="lp-eyebrow">LEBIH DARI SEKADAR HAFAL HURUF</span><h2 id="features-title">Intip keseruan di dalamnya.</h2></div><p>Pilih fiturnya. Coba sedikit.<br>Siap lanjut? Buka versi lengkapnya.</p></div>
        <div class="lp-feature-tabs" role="tablist" aria-label="Sneak peek fitur">
          <button v-for="item in features" :id="'tab-' + item.id" :key="item.id" role="tab" :aria-selected="feature === item.id" :aria-controls="'preview-' + item.id" :tabindex="feature === item.id ? 0 : -1" @click="feature = item.id" @keydown.right.prevent="feature = features[(features.findIndex(f => f.id === feature) + 1) % features.length]!.id; nextTick(() => landing?.querySelector<HTMLElement>('#tab-' + feature)?.focus())" @keydown.left.prevent="feature = features[(features.findIndex(f => f.id === feature) + features.length - 1) % features.length]!.id; nextTick(() => landing?.querySelector<HTMLElement>('#tab-' + feature)?.focus())"><AppIcon :name="item.icon" :size="19" />{{ item.title }}</button>
        </div>
        <div class="lp-feature-stage">
          <div class="lp-feature-info"><span class="lp-preview-badge">SNEAK PEEK · DEMO INTERAKTIF</span><h3>{{ selectedFeature.title }}</h3><p>{{ selectedFeature.copy }}</p><ul v-if="feature === 'race'"><li>Pilihan durasi dan materi</li><li>WPM, akurasi, dan grafik hasil</li><li>Ghost dari percobaan sebelumnya</li></ul><ul v-else-if="feature === 'path'"><li>Tes penempatan untuk menentukan awal</li><li>Bab dan kuis bertahap</li><li>Rangkuman perjalanan pribadi</li></ul><ul v-else><li>Kalender aktivitas belajar</li><li>Riwayat sesi dan rekomendasi latihan</li><li>Badge pencapaian dan raport</li></ul><NuxtLink :to="selectedFeature.to" class="lp-button">{{ selectedFeature.label }}<AppIcon name="arrow" :size="17" /></NuxtLink></div>
          <div :id="'preview-' + feature" :key="feature" class="lp-feature-window" role="tabpanel" :aria-labelledby="'tab-' + feature" tabindex="0"><div class="lp-window-bar"><span><i /><i /><i /></span><small>kanalearn / {{ feature === 'race' ? 'typing-race' : feature === 'path' ? 'perjalanan' : 'progres' }}</small><span class="lp-demo-label">DEMO</span></div>
            <div v-if="feature === 'race'" class="lp-race-preview"><div class="lp-race-heading"><span><AppIcon name="bolt" :size="19" /> TYPING RACE</span><small>COBA SATU KATA</small></div><div class="lp-race-track"><span :style="{ left: Math.min(raceInput.length / raceWord.length, 1) * 82 + '%' }"><KikoMascot decorative class="lp-track-kiko" /></span><span aria-hidden="true">⚑</span></div><div class="lp-race-word"><TypingRaceMascot class="lp-race-avatar" character="kiko" :stroke="raceStroke" :typed-key="raceKey" :mistake="raceMistake" /><span lang="ja">さくら</span><span aria-label="sakura"><b v-for="(letter, index) in raceWord" :key="index" :class="{ typed: raceInput[index]?.toLowerCase() === letter, mistyped: raceInput[index] && raceInput[index]?.toLowerCase() !== letter }">{{ letter }}</b></span></div><label for="lp-race-input">Ketik bacaan huruf di atas</label><input id="lp-race-input" v-model="raceInput" maxlength="6" placeholder="Ketik sakura…" autocomplete="off" autocapitalize="off" :spellcheck="false"><div class="lp-race-status" aria-live="polite"><span>{{ raceComplete ? '✦ Finish! Kamu berhasil.' : raceInput ? raceMistake ? 'Ada huruf yang belum tepat. Coba perbaiki.' : 'Teruskan, Kiko ikut melaju!' : 'Mulai mengetik untuk menggerakkan Kiko.' }}</span><button v-if="raceInput" @click="raceInput = ''">Ulangi ↻</button></div><small class="lp-preview-note">Contoh satu kata · buka Typing Race untuk balapan lengkap.</small></div>
